mapper.select:
select pmi.id, tenant_id, mch_name, state, type, contact_name, contact_tel, pmi.create_time, pmi.update_time from pay_mch_info pmi left join pay_enterprise_info pei on pei.id = pmi.enterprise_info_id left join pay_bank_account_info pbai on pbai.id = pmi.bank_account_info_id
and tenant_id = #{mchPage.tenantId}
and `mch_name` LIKE CONCAT('%', #{mchPage.mchName}, '%')
and state = #{mchPage.state}
and type = #{mchPage.type}
and contact_name = #{mchPage.contactName}
and contact_tel = #{mchPage.contactTel}
order by pmi.create_time desc
